import type { MetadataRoute } from "next";
import { site } from "@/lib/site";

// Baiduspider and Bingbot get explicit allow rules (Baidu in particular
// treats an explicit group as a clearer signal than the wildcard). Both the
// main sitemap and the Chinese sitemap (/sitemap-zh.xml, generated by
// scripts/generate-sitemap-zh.mjs) are listed.
export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      { userAgent: "Baiduspider", allow: "/" },
      { userAgent: "Bingbot", allow: "/" },
      { userAgent: "*", allow: "/" },
    ],
    sitemap: [`${site.url}/sitemap.xml`, `${site.url}/sitemap-zh.xml`],
    host: site.url,
  };
}
